// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(actor, amount);
        uint256 before = address(c).balance;
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok && address(c).balance == before + amount);
    }
}
